    },required:['description','quantity','page_number','unit_price','amount','amount_basis','gst_treatment','printed_gst','suggested_use','classification_confidence','classification_reason']}},
    page_conflict:{type:'boolean'},page_warning:{type:['string','null']},
    confidence:{type:'object',additionalProperties:false,properties:{supplier_name:{type:'string',enum:['high','medium','low']},invoice_number:{type:'string',enum:['high','medium','low']},invoice_date:{type:'string',enum:['high','medium','low']},subtotal:{type:'string',enum:['high','medium','low']},gst:{type:'string',enum:['high','medium','low']},total:{type:'string',enum:['high','medium','low']},expense_category:{type:'string',enum:['high','medium','low']}},required:['supplier_name','invoice_number','invoice_date','subtotal','gst','total','expense_category']}
  },
  required:['document_type','supplier_name','supplier_gst_number','invoice_number','invoice_date','due_date','currency','subtotal','gst','total','description','expense_category','payment_status','payment_method','line_items','page_conflict','page_warning','confidence']
};

function base64Bytes(value:string){
  try{return Math.floor((value.length*3)/4)-(value.endsWith('==')?2:value.endsWith('=')?1:0)}catch{return Number.MAX_SAFE_INTEGER}
}
function normalise(v:any){return String(v||'').toLowerCase().replace(/\b(limited|ltd|the|nz|new zealand)\b/g,' ').replace(/[^a-z0-9]+/g,' ').trim()}
function similarity(a:any,b:any){
  const x=normalise(a),y=normalise(b);if(!x||!y)return 0;if(x===y)return 1;if(x.includes(y)||y.includes(x))return .9;
  const ax=new Set(x.split(/\s+/)),by=new Set(y.split(/\s+/));let same=0;for(const t of ax)if(by.has(t))same++;
  return same/Math.max(ax.size,by.size,1);
}
function extractText(payload:any){
  for(const item of payload?.output||[])for(const c of item?.content||[])if(c?.type==='output_text'&&c?.text)return c.text;
  return '';
}
function cleanDate(v:any){const s=String(v||'').trim();return /^\d{4}-\d{2}-\d{2}$/.test(s)?s:null}

Deno.serve(async(req)=>{
  if(req.method==='OPTIONS')return new Response('ok',{headers:cors});
  if(req.method!=='POST')return out({ok:false,error:'Method not allowed'},405);
  const url=Deno.env.get('SUPABASE_URL');
  const anon=Deno.env.get('SUPABASE_ANON_KEY');
  const service=Deno.env.get('SUPABASE_SERVICE_ROLE_KEY');
  const openai=Deno.env.get('OPENAI_API_KEY');
  if(!url||!anon||!service)return out({ok:false,error:'Server configuration is incomplete'},500);
  if(!openai)return out({ok:false,error:'AI scanning is temporarily unavailable: OPENAI_API_KEY is not configured'},503);
  const auth=req.headers.get('Authorization')||'';
  const client=createClient(url,anon,{global:{headers:{Authorization:auth}}});
  const admin=createClient(url,service);
  let logId:string|null=null;
  try{
    const {data:{user}}=await client.auth.getUser();
    if(!user)return out({ok:false,error:'Not authenticated'},401);
    const body=await req.json();
    const requestedBusinessId=String(body?.business_id||'').trim();
    const {data:currentBusinessId,error:businessError}=await client.rpc('current_business_id');
    if(businessError||!currentBusinessId)return out({ok:false,error:'No active business context found'},403);
    const businessId=requestedBusinessId||currentBusinessId;
    // Confirm the authenticated caller can actually see the requested tenant. This
    // also makes super-admin testing use the business currently open in Finlo.
    const {data:allowedBusiness,error:allowedBusinessError}=await client.from('businesses').select('id').eq('id',businessId).maybeSingle();
    if(allowedBusinessError||!allowedBusiness)return out({ok:false,error:'Business account not available'},403);

    const documents=Array.isArray(body?.documents)?body.documents:[{filename:body?.filename,mime_type:body?.mime_type,file_base64:body?.file_base64}];
    if(!documents.length||documents.length>12)return out({ok:false,error:'Select 1 to 12 pages for one bill.'},400);
    const prepared=documents.map((d:any)=>({filename:String(d?.filename||'page').slice(0,180),mime:String(d?.mime_type||'').toLowerCase(),data:String(d?.file_base64||'').replace(/\s/g,'')}));
    if(prepared.some(d=>!ALLOWED.has(d.mime)||!d.data))return out({ok:false,error:'Each page must be a JPG, PNG, WEBP or PDF.'},400);
    if(prepared.some(d=>base64Bytes(d.data)>MAX_BYTES)||prepared.reduce((n,d)=>n+base64Bytes(d.data),0)>MAX_BYTES)
      return out({ok:false,error:'Combined scan is over 10 MB. Compress the pages or upload a smaller PDF.'},413);
    const filename=prepared.length===1?prepared[0].filename:`${prepared.length} pages`;
    const mime=prepared.length===1?prepared[0].mime:'multi-page';

    // Soft abuse protection: 60 scans per user/business per rolling hour.
    try{
      const since=new Date(Date.now()-60*60*1000).toISOString();
      const {count}=await admin.from('expense_ai_scans').select('id',{count:'exact',head:true}).eq('business_id',businessId).eq('user_id',user.id).gte('created_at',since);
      if((count||0)>=60)return out({ok:false,error:'AI scan limit reached for the last hour. Please try again shortly or enter the expense manually.'},429);
    }catch{/* Logging table may not exist during staged deployment. */}

    const [cats,sups]=await Promise.all([
      client.from('expense_categories').select('id,name,group_name').eq('business_id',businessId).eq('archived',false).order('sort_order').order('name'),
      client.from('suppliers').select('id,supplier_name,trading_name,tax_number').eq('business_id',businessId).eq('archived',false).order('supplier_name')
    ]);
    if(cats.error)throw cats.error;if(sups.error)throw sups.error;
    const categories=(cats.data||[]);
    const suppliers=(sups.data||[]);
    const reviewCategory=categories.find((c:any)=>c.id===body?.review_category_id);

    try{
      const {data}=await admin.from('expense_ai_scans').insert({business_id:businessId,user_id:user.id,status:'processing',filename,mime_type:mime}).select('id').single();
      logId=data?.id||null;
    }catch{/* Optional telemetry only. */}

    const categoryList=categories.map((c:any)=>`${c.name}${c.group_name?` (${c.group_name})`:''}`).join('\n- ');
    const instruction=`Extract expense data from this New Zealand business receipt/invoice. Never invent data. Return null when a field cannot be confidently determined. Dates must be YYYY-MM-DD. Distinguish invoice date from due date. Carefully identify subtotal, GST and final total, including GST-inclusive documents. Keep document amounts exactly as shown rather than silently correcting them. Generate a short useful expense description. Choose exactly one expense_category from the supplied category names; do not create a new category. If none clearly applies, choose Other if it exists, otherwise return null. Payment status should be paid only when the document clearly indicates payment/receipt completion.

Extract EVERY visible purchase item as a separate line_items row with its printed description, quantity, unit price and extended amount. Keep unclear figures null; do not assign the full invoice total to one item. Do not merge different items or silently include GST, freight or discounts in an item. Preserve the amounts exactly as printed. If a separate freight/discount row is visible, include it as its own row. For EACH row identify amount_basis: ex_gst when the printed amount excludes GST, incl_gst when it includes GST, unknown when the document does not establish this. Identify gst_treatment: taxable if the row clearly attracts standard NZ GST at 15%, no_gst if it clearly has no GST, unknown if the document does not establish this. printed_gst is the row's explicitly printed GST if shown; otherwise null. Do not infer GST simply because a supplier or other item is GST registered. Keep an unknown basis or treatment unknown; the reviewer will resolve it. For each item, preselect the single most likely use as an editable suggestion: regular for an ordinary operating cost; stock for products held for resale; supplies for materials used on jobs; depreciable_equipment for durable equipment that may need capitalisation and depreciation; low_value_equipment for a small durable item worth tracking, subject to owner and accountant review. The buyer's actual use may not be on the document: make a cautious best guess with low confidence and explain the uncertainty briefly. The saved invoice category, when supplied below, is context, not proof that every item has the same use. Use needs_review only if even a tentative use cannot be inferred. Never assume a tax deduction or depreciation treatment from price alone. Return a short reason and confidence. The owner will confirm every item later; do not calculate tax depreciation or claim an immediate deduction.

${reviewCategory?`Saved invoice category for review: ${reviewCategory.group_name} · ${reviewCategory.name}.`:''}

Available expense categories:
- ${categoryList||'Other'}

The business currency is generally NZD, but use the document currency when clearly shown.`;
    const content:any[]=[{type:'input_text',text:instruction}];
    content.push({type:'input_text',text:`The ${prepared.length} attached files are ordered pages of ONE supplier bill. Read every page and return ONE combined header and complete item list. Set page_conflict=true if supplier, currency or bill number conflicts, and explain in page_warning. Explain missing or illegible pages in page_warning. Give each purchase item its source page_number (one-based; PDF page if possible). Do not duplicate carried-forward items or include repeated headers, page subtotals or page totals as purchase items. Only the final bill totals belong in subtotal, gst and total. If a page is uncertain leave amounts null for human review.`});
    for(const [index,doc] of prepared.entries()){
      content.push({type:'input_text',text:`Attachment ${index+1} of ${prepared.length}: ${doc.filename}`});
      if(doc.mime==='application/pdf')content.push({type:'input_file',filename:doc.filename,file_data:`data:${doc.mime};base64,${doc.data}`});
      else content.push({type:'input_image',image_url:`data:${doc.mime};base64,${doc.data}`,detail:'high'});
    }

    const model=Deno.env.get('OPENAI_EXPENSE_MODEL')||'gpt-5.6-luna';
    const response=await fetch('https://api.openai.com/v1/responses',{
      method:'POST',
      headers:{Authorization:`Bearer ${openai}`,'Content-Type':'application/json'},
      body:JSON.stringify({model,input:[{role:'user',content}],text:{format:{type:'json_schema',name:'finlo_expense_scan',strict:true,schema}},max_output_tokens:prepared.length>1||prepared.some(d=>d.mime==='application/pdf')?9000:3200})
    });
    const payload=await response.json();
    if(!response.ok){
      const apiMessage=payload?.error?.message||'OpenAI request failed';
      console.error('OpenAI Responses API error',{status:response.status,statusText:response.statusText,error:payload?.error||payload});
      throw new Error(`OpenAI ${response.status}: ${apiMessage}`);
    }
    const text=extractText(payload);if(!text)throw new Error('The AI returned no structured result');
    const result=JSON.parse(text);
    if(result.page_conflict)return out({ok:false,error:result.page_warning||'These pages appear to be from different bills. Separate them before scanning.'},422);
    result.invoice_date=cleanDate(result.invoice_date);result.due_date=cleanDate(result.due_date);
    if(result.currency)result.currency=String(result.currency).toUpperCase().slice(0,3);

    // Use the AI-selected category when it matches an existing category. If it does
    // not, fall back to the tenant's existing "Other" category so category never
    // blocks a scanned expense from being saved.
    let category=categories.find((c:any)=>normalise(c.name)===normalise(result.expense_category));
    if(!category)category=categories.find((c:any)=>normalise(c.name)==='other');
    result.matched_category_id=category?.id||null;
    if(category)result.expense_category=category.name;

    // Match an existing supplier first. GST/tax number is an exact identifier when
    // available; otherwise keep the existing fuzzy-name matching behaviour.
    let best:any=null,bestScore=0;
    const gstKey=String(result.supplier_gst_number||'').replace(/\D/g,'');
    if(gstKey){
      best=suppliers.find((s:any)=>String(s.tax_number||'').replace(/\D/g,'')===gstKey)||null;
      if(best)bestScore=1;
    }
    if(!best){
      for(const s of suppliers){const score=Math.max(similarity(result.supplier_name,s.supplier_name),similarity(result.supplier_name,s.trading_name));if(score>bestScore){best=s;bestScore=score}}
    }
    result.matched_supplier_id=bestScore>=0.72?best?.id||null:null;
    result.supplier_match_score=Number(bestScore.toFixed(2));

    // If the supplier genuinely does not exist yet, create the minimum supplier
    // record automatically and return its id. The normal RLS/business defaults are
    // preserved because this uses the authenticated tenant client.
    if(!result.matched_supplier_id&&String(result.supplier_name||'').trim()){
      const supplierRow:any={
        business_id:businessId,
        supplier_name:String(result.supplier_name).trim(),
        tax_number:String(result.supplier_gst_number||'').trim()||null,
        updated_by:user.id
      };
      const created=await client.from('suppliers').insert(supplierRow).select('id,supplier_name,trading_name,tax_number').single();
      if(created.error)throw created.error;
      result.matched_supplier_id=created.data?.id||null;
      result.supplier_match_score=1;
      result.supplier_created=true;
    }else{
      result.supplier_created=false;
    }

    try{if(logId)await admin.from('expense_ai_scans').update({status:'success',model,openai_response_id:payload?.id||null,input_tokens:payload?.usage?.input_tokens||null,output_tokens:payload?.usage?.output_tokens||null,completed_at:new Date().toISOString()}).eq('id',logId)}catch{}
    return out({ok:true,result});
  }catch(e){
    console.error(e);
    try{if(logId)await admin.from('expense_ai_scans').update({status:'failed',error_message:String(e instanceof Error?e.message:e).slice(0,500),completed_at:new Date().toISOString()}).eq('id',logId)}catch{}
    return out({ok:false,error:e instanceof Error?e.message:'AI scan failed'},400);
  }
});

import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';
import {
  getStripeConfig,
  randomIntegrationSuffix,
  stripeConnectHeaders,
} from '../_shared/payment-config.ts';
import {
  INVOICE_PAYMENTS_MODULE,
  PAYMENT_CORS,
  appOrigin,
  calculateCustomerFee,
  cents,
  createOpaqueToken,
  hashOpaqueToken,
  normaliseCurrency,
  paymentJson,
  roundCents,
} from '../_shared/invoice-payments.ts';

type Context = {
  client: any;
  admin: any;
  user: any;
  businessId: string;
  role: string;
};

function bad(message: string, status = 400) {
  return paymentJson({ error: message }, status);
}

async function contextFor(req: Request, ownerOnly = false): Promise<Context | Response> {
  const url = Deno.env.get('SUPABASE_URL');
  const anon = Deno.env.get('SUPABASE_ANON_KEY');
  const service = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY');
  if (!url || !anon || !service) return bad('Supabase configuration is missing.', 500);

  const auth = req.headers.get('Authorization') || '';
  const client = createClient(url, anon, { global: { headers: { Authorization: auth } } });
  const admin = createClient(url, service);
  const { data: { user } } = await client.auth.getUser();
  if (!user) return bad('Not authenticated.', 401);

  const { data: businessId, error: businessError } = await client.rpc('current_business_id');
  if (businessError || !businessId) return bad('No active business context found.', 403);
  const { data: role, error: roleError } = await client.rpc('v6147_current_business_role', { p_business_id: businessId });
  if (roleError || !role) return bad('Business access could not be verified.', 403);
  if (ownerOnly && role !== 'owner') return bad('Only the Business Owner can manage Stripe payout settings.', 403);

  return { client, admin, user, businessId: String(businessId), role: String(role) };
}

async function requireEnabled(admin: any, businessId: string) {
  const { data, error } = await admin.rpc('v6181_invoice_payments_enabled', { p_business_id: businessId });
  if (error) throw new Error(`Online Invoice Payments is not available: ${error.message}`);
  if (data !== true) throw new Error('Online Invoice Payments has not been enabled for this business by the platform administrator.');
}

async function stripeAccount(secret: string, accountId: string) {
  // API v2 requires JSON headers even for GETs, with indexed include fields.
  const params = new URLSearchParams();
  params.append('include[0]', 'configuration.merchant');
  params.append('include[1]', 'identity');
  params.append('include[2]', 'requirements');
  const response = await fetch(`https://api.stripe.com/v2/core/accounts/${encodeURIComponent(accountId)}?${params.toString()}`, {
    headers: stripeConnectHeaders(secret, true),
  });
  const data = await response.json();
  if (!response.ok) throw new Error(data?.error?.message || 'Unable to retrieve the connected Stripe account.');
  return data;
}

function cardStatus(account: any): string {
  return String(account?.configuration?.merchant?.capabilities?.card_payments?.status || 'not_requested');
}

function connectStatus(account: any): string {
  const status = cardStatus(account);
  if (status === 'active') return 'active';
  if (['restricted', 'inactive'].includes(status)) return 'restricted';
  return 'pending';
}

async function saveAccountStatus(admin: any, businessId: string, account: any) {
  const requirements = account?.requirements || {};
  const patch = {
    stripe_account_id: String(account?.id || ''),
    connect_status: connectStatus(account),
    card_payments_status: cardStatus(account),
    details_submitted: account?.details_submitted === true || account?.identity?.status === 'verified',
    requirements,
    updated_at: new Date().toISOString(),
  };
  const { error } = await admin.from('invoice_payment_settings').upsert({
    business_id: businessId,
    ...patch,
  }, { onConflict: 'business_id' });
  if (error) throw error;
  return patch;
}

async function getSettings(admin: any, businessId: string) {
  const { data, error } = await admin.from('invoice_payment_settings').select('*').eq('business_id', businessId).maybeSingle();
  if (error) throw error;
  return data || {
    business_id: businessId,
    stripe_account_id: null,
    connect_status: 'not_started',
    card_payments_status: 'not_requested',
    details_submitted: false,
    requirements: {},
    fee_mode: 'bear',
    fee_percent: 2.65,
    fee_fixed_amount: 0.30,
    allow_partial_payments: true,
    currency: 'nzd',
  };
}

async function loadPublicPayment(admin: any, token: string) {
  const tokenHash = await hashOpaqueToken(token);
  const { data: link, error: linkError } = await admin
    .from('invoice_payment_links')
    .select('id,business_id,invoice_id,active,expires_at')
    .eq('token_hash', tokenHash)
    .eq('active', true)
    .maybeSingle();
  if (linkError || !link) throw new Error('This payment link is invalid or has been disabled.');
  if (link.expires_at && new Date(link.expires_at) < new Date()) throw new Error('This payment link has expired.');

  const { data: invoice, error: invoiceError } = await admin
    .from('invoices')
    .select('id,business_id,invoice_number,customer_name,customer_email,total,amount_paid,balance_due,due_date,lifecycle_state,company_snapshot')
    .eq('id', link.invoice_id)
    .eq('business_id', link.business_id)
    .single();
  if (invoiceError || !invoice) throw new Error('Invoice not found.');
  if (invoice.lifecycle_state === 'voided') throw new Error('This invoice has been voided.');

  const settings = await getSettings(admin, String(link.business_id));
  const snapshot = invoice.company_snapshot || {};
  const balance = roundCents(Math.max(0, Number(invoice.balance_due ?? (Number(invoice.total || 0) - Number(invoice.amount_paid || 0)))));
  return {
    link,
    invoice,
    settings,
    balance,
    currency: normaliseCurrency(settings.currency || snapshot.currency || 'nzd'),
    businessName: String(snapshot.trading || snapshot.company || 'Your Business'),
  };
}

async function createConnectAccount(ctx: Context, req: Request) {
  await requireEnabled(ctx.admin, ctx.businessId);
  const cfg = await getStripeConfig(ctx.admin, true);
  const { data: business, error: businessError } = await ctx.admin.from('businesses').select('id,name,settings').eq('id', ctx.businessId).single();
  if (businessError || !business) throw new Error('Business details could not be loaded.');
  const existing = await getSettings(ctx.admin, ctx.businessId);
  if (existing.stripe_account_id) {
    const account = await stripeAccount(cfg.secretKey, existing.stripe_account_id);
    const status = await saveAccountStatus(ctx.admin, ctx.businessId, account);
    return paymentJson({ success: true, account_id: existing.stripe_account_id, settings: { ...existing, ...status }, account });
  }

  const settings = business.settings || {};
  const body = {
    contact_email: String(ctx.user.email || '').trim() || undefined,
    display_name: String(business.name || settings.company || settings.trading || 'Frindly business').trim(),
    dashboard: 'full',
    identity: { country: 'nz' },
    configuration: { merchant: { capabilities: { card_payments: { requested: true } } } },
    defaults: { responsibilities: { fees_collector: 'stripe', losses_collector: 'stripe' } },
    include: ['configuration.merchant', 'identity', 'requirements'],
  };
  const response = await fetch('https://api.stripe.com/v2/core/accounts', {
    method: 'POST',
    headers: stripeConnectHeaders(cfg.secretKey, true),
    body: JSON.stringify(body),
  });
  const account = await response.json();
  if (!response.ok) throw new Error(account?.error?.message || 'Stripe could not create the connected account.');
  const status = await saveAccountStatus(ctx.admin, ctx.businessId, account);
  return paymentJson({ success: true, account_id: account.id, settings: status, account });
}

async function createAccountLink(ctx: Context, req: Request) {
  await requireEnabled(ctx.admin, ctx.businessId);
  const cfg = await getStripeConfig(ctx.admin, true);
  const settings = await getSettings(ctx.admin, ctx.businessId);
  if (!settings.stripe_account_id) throw new Error('Start Stripe setup before opening onboarding.');
  const origin = appOrigin(req);
  const returnUrl = `${origin}/?connect=return#settings/payments`;
  const refreshUrl = `${origin}/?connect=refresh#settings/payments`;
  const response = await fetch('https://api.stripe.com/v2/core/account_links', {
    method: 'POST',
    headers: stripeConnectHeaders(cfg.secretKey, true),
    body: JSON.stringify({
      account: settings.stripe_account_id,
      use_case: {
        type: 'account_onboarding',
        account_onboarding: { configurations: ['merchant'], return_url: returnUrl, refresh_url: refreshUrl },
      },
    }),
  });
  const data = await response.json();
  if (!response.ok) throw new Error(data?.error?.message || 'Stripe could not open onboarding.');
  return paymentJson({ url: data.url });
}

async function refreshStatus(ctx: Context) {
  await requireEnabled(ctx.admin, ctx.businessId);
  const cfg = await getStripeConfig(ctx.admin, true);
  const settings = await getSettings(ctx.admin, ctx.businessId);
  if (!settings.stripe_account_id) return paymentJson({ settings });
  const account = await stripeAccount(cfg.secretKey, settings.stripe_account_id);
  const status = await saveAccountStatus(ctx.admin, ctx.businessId, account);
  return paymentJson({ settings: { ...settings, ...status }, account });
}

async function saveSettings(ctx: Context, payload: any) {
  await requireEnabled(ctx.admin, ctx.businessId);
  const feeMode = String(payload?.fee_mode || 'bear');
  if (!['bear', 'split', 'pass'].includes(feeMode)) throw new Error('Choose Bear, Split or Pass for payment fees.');
  const { data, error } = await ctx.admin.from('invoice_payment_settings').upsert({
    business_id: ctx.businessId,
    fee_mode: feeMode,
    allow_partial_payments: payload?.allow_partial_payments !== false,
    updated_at: new Date().toISOString(),
  }, { onConflict: 'business_id' }).select('*').single();
  if (error) throw error;
  return paymentJson({ settings: data });
}

async function details(admin: any, payload: any) {
  const token = String(payload?.token || '').trim();
  if (!token) return bad('Payment token is required.', 400);
  const record = await loadPublicPayment(admin, token);
  const enabled = await admin.rpc('v6181_invoice_payments_enabled', { p_business_id: record.link.business_id });
  if (enabled.error || enabled.data !== true) return bad('Online payments are not currently enabled for this business.', 403);
  const fee = calculateCustomerFee(record.balance, record.settings);
  return paymentJson({
    invoice: {
      invoice_number: record.invoice.invoice_number,
      customer_name: record.invoice.customer_name,
      due_date: record.invoice.due_date,
      total: Number(record.invoice.total || 0),
      amount_paid: Number(record.invoice.amount_paid || 0),
      balance_due: record.balance,
    },
    business_name: record.businessName,
    currency: record.currency,
    fee_mode: record.settings.fee_mode,
    fee_percent: Number(record.settings.fee_percent || 0),
    fee_fixed_amount: Number(record.settings.fee_fixed_amount || 0),
    estimated_customer_fee: fee,
    allow_partial_payments: record.settings.allow_partial_payments === true,
  });
}

async function checkout(admin: any, payload: any, req: Request) {
  const token = String(payload?.token || '').trim();
  if (!token) return bad('Payment token is required.', 400);
  const record = await loadPublicPayment(admin, token);
  const enabled = await admin.rpc('v6181_invoice_payments_enabled', { p_business_id: record.link.business_id });
  if (enabled.error || enabled.data !== true) return bad('Online payments are not currently enabled for this business.', 403);
  if (!record.settings.stripe_account_id || record.settings.connect_status !== 'active') return bad('This business has not finished Stripe payment setup.', 409);
  const cfg = await getStripeConfig(admin, true);
  const account = await stripeAccount(cfg.secretKey, String(record.settings.stripe_account_id));
  if (cardStatus(account) !== 'active') {
    await saveAccountStatus(admin, String(record.link.business_id), account);
    return bad('This business needs to finish Stripe payment setup before accepting payments.', 409);
  }

  const amount = roundCents(Number(payload?.amount));
  if (!Number.isFinite(amount) || amount <= 0) return bad('Enter a payment amount greater than zero.', 400);
  if (!record.settings.allow_partial_payments && Math.abs(amount - record.balance) > 0.005) return bad('This business requires the invoice balance to be paid in full.', 400);
  if (amount > record.balance + 0.005) return bad(`The maximum payment for this invoice is ${record.balance.toFixed(2)}.`, 400);

  const fee = calculateCustomerFee(amount, record.settings);
  const gross = roundCents(amount + fee);
  const currency = record.currency;
  const { data: transaction, error: transactionError } = await admin.from('invoice_payment_transactions').insert({
    business_id: record.link.business_id,
    invoice_id: record.invoice.id,
    payment_link_id: record.link.id,
    stripe_account_id: record.settings.stripe_account_id,
    amount,
    gross_amount: gross,
    customer_fee_amount: fee,
    currency,
    fee_mode: record.settings.fee_mode,
    status: 'pending',
    metadata: { invoice_number: record.invoice.invoice_number, payment_link_id: record.link.id },
  }).select('*').single();
  if (transactionError || !transaction) throw transactionError || new Error('Unable to prepare the payment.');

  const form = new URLSearchParams();
  form.set('mode', 'payment');
  form.set('line_items[0][price_data][currency]', currency);
  form.set('line_items[0][price_data][product_data][name]', `Invoice ${record.invoice.invoice_number}`);
  form.set('line_items[0][price_data][unit_amount]', String(cents(amount)));
  form.set('line_items[0][quantity]', '1');
  if (fee > 0) {
    form.set('line_items[1][price_data][currency]', currency);
    form.set('line_items[1][price_data][product_data][name]', 'Payment processing fee');
    form.set('line_items[1][price_data][unit_amount]', String(cents(fee)));
    form.set('line_items[1][quantity]', '1');
  }
  if (record.invoice.customer_email) form.set('customer_email', String(record.invoice.customer_email));
  form.set('billing_address_collection', 'auto');
  const origin = appOrigin(req);
  form.set('success_url', `${origin}/pay.html?token=${encodeURIComponent(token)}&status=success&session_id={CHECKOUT_SESSION_ID}`);
  form.set('cancel_url', `${origin}/pay.html?token=${encodeURIComponent(token)}&status=cancelled`);
  form.set('client_reference_id', record.invoice.id);
  form.set('metadata[business_id]', String(record.link.business_id));
  form.set('metadata[invoice_id]', String(record.invoice.id));
  form.set('metadata[payment_link_id]', String(record.link.id));
  form.set('metadata[payment_transaction_id]', String(transaction.id));
  form.set('metadata[fee_mode]', String(record.settings.fee_mode));
  form.set('payment_intent_data[metadata][business_id]', String(record.link.business_id));
  form.set('payment_intent_data[metadata][invoice_id]', String(record.invoice.id));
  form.set('payment_intent_data[metadata][payment_transaction_id]', String(transaction.id));
  form.set('integration_identifier', `frindly_invoice_${randomIntegrationSuffix()}`);

  const response = await fetch('https://api.stripe.com/v1/checkout/sessions', {
    method: 'POST',
    headers: { ...stripeConnectHeaders(cfg.secretKey), 'Stripe-Account': String(record.settings.stripe_account_id) },
    body: form,
  });
  const session = await response.json();
  if (!response.ok) {
    await admin.from('invoice_payment_transactions').update({ status: 'failed', failure_reason: session?.error?.message || 'Stripe Checkout creation failed.', updated_at: new Date().toISOString() }).eq('id', transaction.id);
    throw new Error(session?.error?.message || 'Unable to open Stripe Checkout.');
  }
  await admin.from('invoice_payment_transactions').update({
    stripe_checkout_session_id: session.id,
    status: 'processing',
    updated_at: new Date().toISOString(),
  }).eq('id', transaction.id);
  await admin.from('invoice_payment_links').update({ last_used_at: new Date().toISOString(), updated_at: new Date().toISOString() }).eq('id', record.link.id);
  return paymentJson({ url: session.url, transaction_id: transaction.id });
}

Deno.serve(async (req) => {
  if (req.method === 'OPTIONS') return new Response('ok', { headers: PAYMENT_CORS });
  try {
    const url = Deno.env.get('SUPABASE_URL');
    const service = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY');
    if (!url || !service) return bad('Supabase configuration is missing.', 500);
    const admin = createClient(url, service);
    const payload = await req.json().catch(() => ({}));
    const action = String(payload?.action || '');

    if (action === 'details') return await details(admin, payload);
    if (action === 'checkout') return await checkout(admin, payload, req);

    const ctx = await contextFor(req, action !== 'status');
    if (ctx instanceof Response) return ctx;
    await requireEnabled(ctx.admin, ctx.businessId);
    if (action === 'get-settings') return paymentJson({ settings: await getSettings(ctx.admin, ctx.businessId) });
    if (action === 'save-settings') return await saveSettings(ctx, payload);
    if (action === 'create-account') return await createConnectAccount(ctx, req);
    if (action === 'create-account-link') return await createAccountLink(ctx, req);
    if (action === 'status') return await refreshStatus(ctx);
    return bad('Unknown invoice payment action.', 400);
  } catch (error) {
    return bad(error instanceof Error ? error.message : 'Invoice payment request failed.', 400);
  }
});

export const STRIPE_API_VERSION = '2026-07-29.dahlia';
// Stripe Connect Accounts v2 endpoints use their current preview API surface
// separately from the platform subscription API version above.
export const STRIPE_CONNECT_API_VERSION = '2026-08-26.preview';

/** Read Stripe credentials from Supabase Vault, with env vars as a deployment fallback. */
export async function getStripeConfig(admin: any, requireEnabled = false) {
  const { data: row, error: rowError } = await admin
    .from('payment_provider_settings')
    .select('provider,enabled,mode,public_config')
    .eq('provider', 'stripe')
    .maybeSingle();

  if (rowError && !String(rowError.message || '').includes('payment_provider_settings')) {
    throw rowError;
  }

  const { data: secretText, error: secretError } = await admin.rpc(
    'v34_get_payment_provider_secret',
    { p_provider: 'stripe' },
  );

  let stored: Record<string, string> = {};
  if (!secretError && secretText) {
    try {
      stored = JSON.parse(secretText) || {};
    } catch {
      stored = {};
    }
  }

  const secretKey = String(stored.secret_key || Deno.env.get('STRIPE_SECRET_KEY') || '').trim();
  const webhookSecret = String(stored.webhook_secret || Deno.env.get('STRIPE_WEBHOOK_SECRET') || '').trim();
  const publishableKey = String(row?.public_config?.publishable_key || '').trim();
  const enabled = row ? row.enabled === true : Boolean(secretKey);
  const mode = row?.mode === 'live' ? 'live' : 'test';

  if (requireEnabled && !enabled) {
    throw new Error('Stripe payments are disabled in Super Admin → Payment gateway settings.');
  }
  if (!secretKey) {
    throw new Error('Stripe secret key is not configured. Add it in Super Admin → Payment gateway settings.');
  }

  // Catch accidental test/live mismatches before a customer reaches Checkout.
  const keyLooksLive = /_(live)_/.test(secretKey);
  const keyLooksTest = /_(test)_/.test(secretKey);
  if (mode === 'live' && keyLooksTest) throw new Error('Stripe is set to Live mode but a test API key is configured.');
  if (mode === 'test' && keyLooksLive) throw new Error('Stripe is set to Test mode but a live API key is configured.');

  return { secretKey, webhookSecret, publishableKey, enabled, mode };
}

export function stripeHeaders(secretKey: string, form = false): Record<string, string> {
  return {
    Authorization: `Bearer ${secretKey}`,
    'Stripe-Version': STRIPE_API_VERSION,
    ...(form ? { 'Content-Type': 'application/x-www-form-urlencoded' } : {}),
  };
}

export function stripeConnectHeaders(secretKey: string, json = false): Record<string, string> {
  return {
    Authorization: `Bearer ${secretKey}`,
    'Stripe-Version': STRIPE_CONNECT_API_VERSION,
    ...(json ? { 'Content-Type': 'application/json' } : { 'Content-Type': 'application/x-www-form-urlencoded' }),
  };
}

export function randomIntegrationSuffix(): string {
  const alphabet = 'abcdefghijklmnopqrstuvwxyz';
  const bytes = new Uint8Array(8);
  crypto.getRandomValues(bytes);
  return Array.from(bytes, (byte) => alphabet[byte % alphabet.length]).join('');
}

export const INVOICE_PAYMENTS_MODULE = 'invoice_payments';

export const PAYMENT_CORS = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
};

export const paymentJson = (value: unknown, status = 200) => new Response(
  JSON.stringify(value),
  { status, headers: { ...PAYMENT_CORS, 'Content-Type': 'application/json' } },
);

export function roundCents(value: number): number {
  return Math.round((Number(value) + Number.EPSILON) * 100) / 100;
}

export function calculateCustomerFee(amount: number, settings: any): number {
  const base = Math.max(0, roundCents(amount));
  const mode = String(settings?.fee_mode || 'bear');
  if (mode === 'bear') return 0;

  const percent = Math.max(0, Number(settings?.fee_percent || 0)) / 100;
  const fixed = Math.max(0, Number(settings?.fee_fixed_amount || 0));
  // Gross-up the fee so the configured processing estimate is covered when
  // the business passes it through. Split allocates half of that estimate.
  const grossedUp = percent >= 0.9999 ? fixed : (base * percent + fixed) / (1 - percent);
  return roundCents(mode === 'split' ? grossedUp / 2 : grossedUp);
}

export function appOrigin(req: Request, requested?: unknown): string {
  const configured = String(Deno.env.get('PUBLIC_APP_URL') || '').trim();
  const candidate = String(requested || req.headers.get('origin') || configured || 'https://frindly.co.nz').trim();
  try {
    const url = new URL(candidate);
    if (!['https:', 'http:'].includes(url.protocol)) throw new Error('Unsupported app URL protocol');
    url.pathname = '';
    url.search = '';
    url.hash = '';
    return url.toString().replace(/\/$/, '');
  } catch {
    return configured || 'https://frindly.co.nz';
  }
}

export function createOpaqueToken(): string {
  const bytes = new Uint8Array(32);
  crypto.getRandomValues(bytes);
  let binary = '';
  for (const byte of bytes) binary += String.fromCharCode(byte);
  return btoa(binary).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/g, '');
}

export async function hashOpaqueToken(token: string): Promise<string> {
  const digest = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(token));
  return Array.from(new Uint8Array(digest), (byte) => byte.toString(16).padStart(2, '0')).join('');
}

export function cents(value: unknown): number {
  return Math.round(Math.max(0, Number(value || 0)) * 100);
}

export function normaliseCurrency(value: unknown): string {
  const currency = String(value || 'nzd').trim().toLowerCase();
  return /^[a-z]{3}$/.test(currency) ? currency : 'nzd';
}

import Stripe from 'npm:stripe@22.4.0';
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';
import { getStripeConfig, stripeHeaders, STRIPE_API_VERSION } from '../_shared/payment-config.ts';
import { subscriptionPlanPatch, subscriptionCancellationPatch } from '../_shared/subscription-billing.ts';
import { platformFrom, validReplyTo } from '../_shared/email-sender.ts';

function subscriptionBillingPeriod(subscription:any){
  // Frindly Checkout creates one recurring plan item. New Stripe versions keep
  // its billing dates on that item; older event snapshots used the subscription.
  const item=subscription?.items?.data?.[0];
  const start=subscription?.current_period_start??item?.current_period_start;
  const end=subscription?.current_period_end??item?.current_period_end;
  const startDate=new Date(start*1000),endDate=new Date(end*1000);
  if(!Number.isFinite(start)||!Number.isFinite(end)||end<start||
    !Number.isFinite(startDate.getTime())||!Number.isFinite(endDate.getTime())){
    throw new Error('Stripe subscription billing period is missing or invalid.');
  }
  return {current_period_start:startDate.toISOString(),current_period_end:endDate.toISOString()};
}

Deno.serve(async(req)=>{
  const url=Deno.env.get('SUPABASE_URL');
  const service=Deno.env.get('SUPABASE_SERVICE_ROLE_KEY');
  if(!url||!service) return new Response('Missing Supabase configuration',{status:500});

  const db=createClient(url,service);
  let cfg;
  try{cfg=await getStripeConfig(db,false)}catch(e){return new Response(e instanceof Error?e.message:'Missing Stripe configuration',{status:500})}

  const secret=cfg.secretKey;
  const wh=cfg.webhookSecret;
  if(!wh) return new Response('Stripe webhook signing secret is not configured in Super Admin → Payment gateway settings.',{status:500});

  const stripe=new Stripe(secret,{apiVersion:STRIPE_API_VERSION});
  const sig=req.headers.get('stripe-signature');
  if(!sig) return new Response('Missing signature',{status:400});

  let event:Stripe.Event;
  try{
    event=await stripe.webhooks.constructEventAsync(await req.text(),sig,wh);
  }catch(e){
    return new Response(`Webhook signature error: ${e instanceof Error?e.message:'invalid'}`,{status:400});
  }

  const referralEvent=async(bid:string|undefined,eventName:string)=>{
    if(!bid)return;
    const {error}=await db.rpc('v6151_process_referral_event',{p_business_id:bid,p_event:eventName});
    if(error) throw new Error(`Referral event ${eventName} failed: ${error.message}`);
  };

  const invoiceSubscriptionId=(invoice:Stripe.Invoice)=>{
    const related=(invoice as any).parent?.subscription_details?.subscription||(invoice as any).subscription;
    return typeof related==='string'?related:String(related?.id||'');
  };
  const recordRefereeDiscount=async(bid:string,referralId:string|undefined,couponId:string|undefined)=>{
    if(!bid||!referralId||!couponId)return;
    const {data,error}=await db.from('referrals')
      .update({referee_checkout_coupon_id:couponId})
      .eq('id',referralId).eq('referred_business_id',bid)
      .is('referee_checkout_coupon_id',null).select('id');
    if(error)throw error;
    // On retries the existing coupon is already recorded; only a missing
    // referral signals a mismatch that would otherwise award twice.
    if(!data?.length){
      const {data:existing,error:lookupError}=await db.from('referrals')
        .select('referee_checkout_coupon_id').eq('id',referralId)
        .eq('referred_business_id',bid).maybeSingle();
      if(lookupError||existing?.referee_checkout_coupon_id!==couponId)
        throw new Error('Referral coupon could not be matched to the business.');
    }
  };

  const resolveBusiness=async(invoice:Stripe.Invoice)=>{
    const subscriptionId=invoiceSubscriptionId(invoice);
    if(subscriptionId){
      const {data:s}=await db.from('subscriptions').select('business_id').eq('stripe_subscription_id',subscriptionId).maybeSingle();
      if(s?.business_id) return String(s.business_id);
      try{
        const sub=await stripe.subscriptions.retrieve(subscriptionId);
        if(sub.metadata?.business_id) return String(sub.metadata.business_id);
      }catch{}
    }

    const customerId=invoice.customer?String(invoice.customer):'';
    if(customerId){
      const {data:s}=await db.from('subscriptions').select('business_id').eq('stripe_customer_id',customerId).limit(1).maybeSingle();
      if(s?.business_id) return String(s.business_id);
    }
    return '';
  };

  const applyFinloCredit=async(invoice:Stripe.Invoice)=>{
    // Credits belong to the subscriber's Billing invoice, never an unrelated
    // invoice that happens to share the same Stripe customer.
    if(!invoiceSubscriptionId(invoice))return;
    const invoiceId=String(invoice.id||'');
    const customerId=invoice.customer?String(invoice.customer):'';
    if(!invoiceId||!customerId)return;

    const bid=await resolveBusiness(invoice);
    if(!bid)return;

    const currency=String(invoice.currency||'nzd').toUpperCase();
    const {data:reservation,error:reserveError}=await db.rpc('v6152_reserve_credits',{
      p_business_id:bid,
      p_stripe_invoice_id:invoiceId,
      p_stripe_customer_id:customerId,
      p_currency:currency
    });

    if(reserveError)throw new Error(`Finlo credit reservation failed for ${invoiceId}: ${reserveError.message}`);

    const amount=Number(reservation?.amount||0);
    const applicationId=String(reservation?.applicationId||'');
    if(reservation?.alreadyCredited||amount<=0||!applicationId)return;

    try{
      const form=new URLSearchParams();
      form.set('amount',String(-Math.round(amount*100)));
      form.set('currency',currency.toLowerCase());
      form.set('description','Finlo credit applied to subscription');
      form.set('metadata[finlo_redemption_id]',applicationId);
      form.set('metadata[finlo_business_id]',bid);
      form.set('metadata[stripe_invoice_id]',invoiceId);

      const r=await fetch(`https://api.stripe.com/v1/customers/${encodeURIComponent(customerId)}/balance_transactions`,{
        method:'POST',
        headers:{
          Authorization:`Bearer ${secret}`,
          'Content-Type':'application/x-www-form-urlencoded',
          'Stripe-Version':STRIPE_API_VERSION,
          'Idempotency-Key':`finlo-credit-${applicationId}`
        },
        body:form
      });
      const d=await r.json();
      if(!r.ok) throw new Error(d?.error?.message||'Unable to apply Finlo credit in Stripe');

      const {error:completeError}=await db.rpc('v6152_complete_credit_redemption',{
        p_application_id:applicationId,
        p_stripe_balance_transaction_id:String(d.id||'')
      });
      if(completeError) throw new Error(completeError.message);
    }catch(e){
      const msg=e instanceof Error?e.message:'Stripe credit application failed';
      const {error:releaseError}=await db.rpc('v6152_release_credit_redemption',{
        p_application_id:applicationId,
        p_error:msg
      });
      if(releaseError) console.warn('Finlo credit release failed',applicationId,releaseError.message);
      throw e;
    }
  };

  try{
    const connectedPaymentIntent=async(accountId:string,paymentIntentId:string)=>{
      if(!accountId||!paymentIntentId)return null;
      const params=new URLSearchParams();params.append('expand[]','latest_charge.balance_transaction');
      const response=await fetch(`https://api.stripe.com/v1/payment_intents/${encodeURIComponent(paymentIntentId)}?${params.toString()}`,{headers:{...stripeHeaders(secret), 'Stripe-Account':accountId}});
      const data=await response.json();
      if(!response.ok){console.warn('Connected payment intent lookup failed',paymentIntentId,data?.error?.message||response.status);return null}
      return data;
    };

    const sendOnlineReceipt=async(transactionId:string)=>{
      const resendKey=Deno.env.get('RESEND_API_KEY');
      if(!resendKey)return;
      const {data:tx,error:txError}=await db.from('invoice_payment_transactions').select('id,amount,gross_amount,customer_fee_amount,currency,status,payment_date,stripe_payment_intent_id,stripe_checkout_session_id,metadata,invoices(invoice_number,customer_name,customer_email,total,balance_due),businesses(name,settings)').eq('id',transactionId).maybeSingle();
      if(txError||!tx||tx.status!=='succeeded'||!tx.invoices?.customer_email)return;
      const settings=tx.businesses?.settings||{},invoice=tx.invoices||{},currency=String(tx.currency||settings.currency||'NZD').toUpperCase();
      const {data:claim,error:claimError}=await db.rpc('v6179_claim_invoice_payment_receipt',{p_transaction_id:transactionId});
      if(claimError)throw claimError;
      if(!claim?.claimed)return;
      const claimToken=String(claim.claim_token);

      const businessName=String(settings.trading||settings.company||tx.businesses?.name||'Your Business');
      const esc=(value:any)=>String(value??'').replace(/[&<>"']/g,(m)=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]||m));
      const money=(value:any)=>{try{return new Intl.NumberFormat('en-NZ',{style:'currency',currency}).format(Number(value||0))}catch{return `${currency} ${Number(value||0).toFixed(2)}`}};
      const invoiceNumber=String(invoice.invoice_number||'Invoice');
      const subject=`Payment received for ${invoiceNumber} · ${businessName}`;
      const html=`<div style="font-family:Arial,sans-serif;line-height:1.6;color:#24313a"><h2>Payment received</h2><p>Hi ${esc(invoice.customer_name||'Customer')},</p><p>${esc(businessName)} has received your payment for invoice <strong>${esc(invoiceNumber)}</strong>.</p><table cellpadding="6" cellspacing="0"><tr><td>Invoice payment</td><td><strong>${money(tx.amount)}</strong></td></tr>${Number(tx.customer_fee_amount||0)>0?`<tr><td>Payment processing fee</td><td>${money(tx.customer_fee_amount)}</td></tr>`:''}<tr><td>Total charged</td><td><strong>${money(tx.gross_amount)}</strong></td></tr><tr><td>Remaining invoice balance</td><td>${money(invoice.balance_due)}</td></tr></table><p>Reference: ${esc(tx.stripe_payment_intent_id||tx.stripe_checkout_session_id||'Stripe payment')}</p><p>Thank you,<br>${esc(businessName)}</p></div>`;
      try{
      const response=await fetch('https://api.resend.com/emails',{method:'POST',headers:{Authorization:`Bearer ${resendKey}`,'Content-Type':'application/json','Idempotency-Key':String(claim.idempotency_key)},body:JSON.stringify({from:platformFrom(businessName),to:[invoice.customer_email],reply_to:validReplyTo(settings.outboundEmail||settings.email),subject,html})});
      if(!response.ok)throw new Error(`Resend HTTP ${response.status}: ${(await response.text()).slice(0,300)}`);
      const sent=await response.json();
      const {data:completed,error:completeError}=await db.rpc('v6179_complete_invoice_payment_receipt',{p_transaction_id:transactionId,p_claim_token:claimToken,p_resend_message_id:String(sent?.id||'')});
      if(completeError||completed!==true)throw completeError||new Error('Receipt completion not confirmed');
      }catch(e){
        // Never automatically release a claimed receipt after a provider request.
        // An expired claim is quarantined for manual Resend reconciliation.
        console.warn('Invoice receipt delivery requires reconciliation',transactionId,e);
      }
    };

    // Validate the Stripe object against the transaction created by Frindly.
    const verifiedInvoiceTransaction=async(session:any,accountId:string,transactionId:string)=>{
      const {data:tx,error}=await db.from('invoice_payment_transactions')
        .select('id,stripe_account_id,stripe_checkout_session_id,stripe_payment_intent_id,gross_amount,currency,status')
        .eq('id',transactionId).maybeSingle();
      if(error)throw error;
      if(!tx)throw new Error('Stripe payment transaction does not exist.');
      const sessionId=String(session?.id||'');
      const intentId=String(session?.payment_intent||'');
      if(!accountId||String(tx.stripe_account_id||'')!==accountId)throw new Error('Stripe connected account mismatch.');
      if(sessionId&&tx.stripe_checkout_session_id&&tx.stripe_checkout_session_id!==sessionId)throw new Error('Stripe Checkout session mismatch.');
      if(intentId&&tx.stripe_payment_intent_id&&tx.stripe_payment_intent_id!==intentId)throw new Error('Stripe payment intent mismatch.');
      const amount=Number(session?.amount_total);
      if(!Number.isSafeInteger(amount)||amount<=0||amount!==Math.round(Number(tx.gross_amount)*100))throw new Error('Stripe payment amount mismatch.');
      if(String(session?.currency||'').toLowerCase()!==String(tx.currency||'').toLowerCase())throw new Error('Stripe payment currency mismatch.');
      return tx;
    };
    const verifiedCommunityCampaign=async(session:any,campaignId:string)=>{
      if(String((event as any).account||''))throw new Error('Community ad payment must be on the platform account.');
      const {data:campaign,error}=await db.from('community_ad_campaigns')
        .select('id,stripe_checkout_session_id,stripe_payment_intent_id,price_charged,currency,payment_status,status')
        .eq('id',campaignId).maybeSingle();
      if(error)throw error;
      if(!campaign)throw new Error('Community ad campaign does not exist.');
      if(!session?.id||campaign.stripe_checkout_session_id!==String(session.id))throw new Error('Community ad Checkout session mismatch.');
      if(campaign.stripe_payment_intent_id&&session.payment_intent&&campaign.stripe_payment_intent_id!==String(session.payment_intent))throw new Error('Community ad payment intent mismatch.');
      if(!Number.isSafeInteger(Number(session.amount_total))||Number(session.amount_total)!==Math.round(Number(campaign.price_charged)*100))throw new Error('Community ad payment amount mismatch.');
      if(String(session.currency||'').toLowerCase()!==String(campaign.currency||'').toLowerCase())throw new Error('Community ad payment currency mismatch.');
      return campaign;
    };
    const settleOnlineCheckout=async(session:any,success:boolean)=>{
      const accountId=String((event as any).account||'');
      const transactionId=String(session?.metadata?.payment_transaction_id||'');
      if(!accountId||!transactionId)return false;
      const paymentIntentId=String(session?.payment_intent||'');
      const tx=await verifiedInvoiceTransaction(session,accountId,transactionId);
      if(!success){
        const {error}=await db.from('invoice_payment_transactions').update({status:'failed',failure_reason:'Stripe reported that the customer payment failed.',stripe_checkout_session_id:session?.id||null,stripe_payment_intent_id:paymentIntentId||null,stripe_event_id:event.id,updated_at:new Date().toISOString()}).eq('id',transactionId).neq('status','succeeded').neq('status','needs_review');
        if(error)throw error;
        return true;
      }

      // Payments flagged for manual review must not be automatically settled by delayed Stripe events.
      if(tx.status==='succeeded'||tx.status==='needs_review')return true;
      const intent=paymentIntentId?await connectedPaymentIntent(accountId,paymentIntentId):null;
      const charge=intent?.latest_charge&&typeof intent.latest_charge==='object'?intent.latest_charge:null;
      const balance=intent?.latest_charge?.balance_transaction&&typeof intent.latest_charge.balance_transaction==='object'?intent.latest_charge.balance_transaction:null;
      const grossAmount=Number(session?.amount_total||intent?.amount||0)/100;
      const stripeFee=balance?.fee==null?null:Number(balance.fee)/100;
      const netAmount=balance?.net==null?null:Number(balance.net)/100;
      const patch:any={
        status:'processing',
        stripe_checkout_session_id:session?.id||null,
        stripe_payment_intent_id:paymentIntentId||null,
        stripe_charge_id:charge?.id?String(charge.id):null,
        stripe_event_id:event.id,
        gross_amount:grossAmount>0?grossAmount:undefined,
        stripe_fee_amount:stripeFee,
        net_amount:netAmount,
        payment_date:new Date(Number(event.created||Date.now()/1000)*1000).toISOString(),
        updated_at:new Date().toISOString()
      };
      Object.keys(patch).forEach(k=>patch[k]===undefined&&delete patch[k]);
      const {error:updateError}=await db.from('invoice_payment_transactions').update(patch).eq('id',transactionId).neq('status','succeeded');
      if(updateError)throw updateError;
      const {error:recordError}=await db.rpc('v6181_record_online_invoice_payment',{
        p_transaction_id:transactionId,
        p_payment_date:new Date(Number(event.created||Date.now()/1000)*1000).toISOString().slice(0,10),
        p_reference:`Stripe Checkout ${String(session?.id||paymentIntentId||'payment')}`
      });
      if(recordError)throw recordError;
      await sendOnlineReceipt(transactionId);
      return true;
    };

    const settleCommunityAdCheckout=async(session:any,success:boolean)=>{
      const campaignId=String(session?.metadata?.community_ad_campaign_id||'');
      if(!campaignId)return false;
      const paymentIntentId=session?.payment_intent?String(session.payment_intent):'';
      const campaign=await verifiedCommunityCampaign(session,campaignId);
      if(campaign.payment_status==='paid')return true;
      const patch:any={
        stripe_checkout_session_id:session?.id||null,
        stripe_payment_intent_id:paymentIntentId||null,
        payment_status:success?'paid':'failed',
        status:success?'pending_review':'pending_payment',
        updated_at:new Date().toISOString()
      };
      const {error}=await db.from('community_ad_campaigns').update(patch).eq('id',campaignId).neq('payment_status','paid');
      if(error)throw error;
      return true;
    };

    const settleOnlinePaymentIntent=async(intent:any,success:boolean)=>{
      const accountId=String((event as any).account||'');
      const transactionId=String(intent?.metadata?.payment_transaction_id||'');
      if(!accountId||!transactionId)return false;
      const sessionLike={id:null,payment_intent:intent?.id,amount_total:intent?.amount_received||intent?.amount,currency:intent?.currency,metadata:intent?.metadata};
      if(!success){
        await verifiedInvoiceTransaction(sessionLike,accountId,transactionId);
        const {error}=await db.from('invoice_payment_transactions').update({status:'failed',failure_reason:'Stripe reported that the payment intent failed.',stripe_payment_intent_id:intent?.id||null,stripe_event_id:event.id,updated_at:new Date().toISOString()}).eq('id',transactionId).neq('status','succeeded').neq('status','needs_review');
        if(error)throw error;
        return true;
      }
      return settleOnlineCheckout(sessionLike,true);
    };

    // V61.52 additive behavior: when Stripe creates the next subscription invoice,
    // transfer eligible earned Finlo credit to the Stripe customer invoice balance.
    // Stripe then applies that credit to the invoice during normal finalization.
    if(event.type==='invoice.created'){
      const invoice=event.data.object as Stripe.Invoice;
      await applyFinloCredit(invoice);
    }

    // Existing V61.51 subscription + referral behavior below remains unchanged.
    if(event.type==='checkout.session.completed'){
      const cs=event.data.object as Stripe.Checkout.Session;
      if(cs.metadata?.community_ad_campaign_id){
        if(cs.payment_status==='paid' && await settleCommunityAdCheckout(cs,true)) return new Response('ok');
        // Checkout completion alone is not proof of failure for delayed payment methods.
        await verifiedCommunityCampaign(cs,String(cs.metadata.community_ad_campaign_id));
        return new Response('ok');
      }
      if(cs.metadata?.payment_transaction_id&&cs.payment_status!=='paid'){
        await verifiedInvoiceTransaction(cs,String((event as any).account||''),String(cs.metadata.payment_transaction_id));
        const {error}=await db.from('invoice_payment_transactions').update({status:'processing',stripe_checkout_session_id:cs.id,stripe_payment_intent_id:cs.payment_intent?String(cs.payment_intent):null,stripe_event_id:event.id,updated_at:new Date().toISOString()}).eq('id',String(cs.metadata.payment_transaction_id)).neq('status','succeeded').neq('status','needs_review');
        if(error)throw error;
        return new Response('ok');
      }
      if(await settleOnlineCheckout(cs,true)) return new Response('ok');
      const bid=cs.metadata?.business_id;
      const pid=cs.metadata?.plan_id;
      if(bid&&pid&&cs.subscription){
        const sub=await stripe.subscriptions.retrieve(String(cs.subscription));
        // Checkout is the only place the referee's free months are redeemed.
        // Persist that redemption before a later paid invoice issues rewards.
        await recordRefereeDiscount(bid,cs.metadata?.referral_id,cs.metadata?.referee_coupon_id);
        const {error:subscriptionError}=await db.from('subscriptions').update({
          plan_id:pid,
          status:'active',
          stripe_customer_id:String(cs.customer||''),
          stripe_subscription_id:sub.id,
          ...subscriptionBillingPeriod(sub),
          ...subscriptionCancellationPatch(sub),
          trial_ends_at:null,
          billing_interval:cs.metadata?.billing_interval==='annual'?'annual':'monthly',
          updated_at:new Date().toISOString()
        }).eq('business_id',bid);
        if(subscriptionError)throw subscriptionError;
        await referralEvent(bid,'subscription_activated');
      }
    }

    if(event.type==='checkout.session.async_payment_succeeded'){
      const cs=event.data.object as Stripe.Checkout.Session;
      if(await settleCommunityAdCheckout(cs,true)) return new Response('ok');
      if(await settleOnlineCheckout(cs,true)) return new Response('ok');
    }

    if(event.type==='checkout.session.async_payment_failed'){
      const cs=event.data.object as Stripe.Checkout.Session;
      if(await settleCommunityAdCheckout(cs,false)) return new Response('ok');
      if(await settleOnlineCheckout(cs,false)) return new Response('ok');
    }

    if(event.type==='payment_intent.succeeded'){
      const intent=event.data.object as Stripe.PaymentIntent;
      if(await settleOnlinePaymentIntent(intent,true)) return new Response('ok');
    }

    if(event.type==='payment_intent.payment_failed'){
      const intent=event.data.object as Stripe.PaymentIntent;
      if(await settleOnlinePaymentIntent(intent,false)) return new Response('ok');
    }

    if(event.type==='customer.subscription.created'||event.type==='customer.subscription.updated'||event.type==='customer.subscription.deleted'){
      // Read current state so delayed cancellation events cannot undo Keep subscription.
      const snapshot=event.data.object as Stripe.Subscription;
      const sub=event.type==='customer.subscription.deleted'?snapshot:await stripe.subscriptions.retrieve(snapshot.id);
      const bid=sub.metadata?.business_id;
      if(bid){
        const {data:current,error:currentError}=await db.from('subscriptions').select('stripe_subscription_id,status').eq('business_id',bid).maybeSingle();
        if(currentError)throw currentError;
        // A deleted older subscription must not cancel its replacement.
        if(current?.stripe_subscription_id&&current.stripe_subscription_id!==sub.id&&
          (event.type==='customer.subscription.deleted'||current.status!=='canceled'))return new Response('ok');
        const status=event.type==='customer.subscription.deleted'?'canceled':(sub.status==='active'?'active':sub.status==='past_due'?'past_due':sub.status==='trialing'?'trialing':'canceled');
        const patch:any={
          status,
          ...subscriptionBillingPeriod(sub),
          ...subscriptionCancellationPatch(sub),
          updated_at:new Date().toISOString()
        };
        // Portal changes update the Stripe price, not the original Checkout metadata.
        Object.assign(patch,await subscriptionPlanPatch(db,sub));
        patch.trial_ends_at=sub.trial_end?new Date(sub.trial_end*1000).toISOString():null;
        if(sub.customer)patch.stripe_customer_id=String(sub.customer);
        patch.stripe_subscription_id=sub.id;
        if(current?.status==='suspended')patch.status='suspended';
        const {error:subscriptionError}=await db.from('subscriptions').update(patch).eq('business_id',bid);
        if(subscriptionError)throw subscriptionError;
        if(status==='active') await referralEvent(bid,'subscription_activated');
      }
    }

    if(event.type==='invoice.payment_failed'){
      const invoice=event.data.object as Stripe.Invoice;
      const bid=await resolveBusiness(invoice);
      if(bid) await db.from('subscriptions').update({status:'past_due',updated_at:new Date().toISOString()}).eq('business_id',bid);
    }

    if(event.type==='invoice.payment_succeeded'){
      const invoice=event.data.object as Stripe.Invoice;
      const subscriptionId=invoiceSubscriptionId(invoice);
      // A fully discounted invoice is successful, but no first payment has been received.
      if(subscriptionId&&Number(invoice.amount_paid||0)>0){
        const {data:s}=await db.from('subscriptions').select('business_id').eq('stripe_subscription_id',subscriptionId).maybeSingle();
        let bid=s?.business_id;
        if(!bid){
          try{
            const sub=await stripe.subscriptions.retrieve(subscriptionId);
            bid=sub.metadata?.business_id;
          }catch{}
        }
        if(bid){
          const {data:pending,error:pendingError}=await db.from('referrals')
            .select('id').eq('referred_business_id',bid)
            .in('status',['signed_up','pending_qualification','qualified']).maybeSingle();
          if(pendingError)throw pendingError;
          if(pending){
            const billingSub=await stripe.subscriptions.retrieve(subscriptionId);
            await recordRefereeDiscount(bid,billingSub.metadata?.referral_id,billingSub.metadata?.referee_coupon_id);
          }
          await referralEvent(bid,'first_successful_payment');
        }
      }
    }

    return new Response('ok');
  }catch(e){
    return new Response(e instanceof Error?e.message:'Webhook failed',{status:500});
  }
});

export const STRIPE_API_VERSION = '2026-07-29.dahlia';
// Stripe Connect Accounts v2 endpoints use their current preview API surface
// separately from the platform subscription API version above.
export const STRIPE_CONNECT_API_VERSION = '2026-08-26.preview';

/** Read Stripe credentials from Supabase Vault, with env vars as a deployment fallback. */
export async function getStripeConfig(admin: any, requireEnabled = false) {
  const { data: row, error: rowError } = await admin
    .from('payment_provider_settings')
    .select('provider,enabled,mode,public_config')
    .eq('provider', 'stripe')
    .maybeSingle();

  if (rowError && !String(rowError.message || '').includes('payment_provider_settings')) {
    throw rowError;
  }

  const { data: secretText, error: secretError } = await admin.rpc(
    'v34_get_payment_provider_secret',
    { p_provider: 'stripe' },
  );

  let stored: Record<string, string> = {};
  if (!secretError && secretText) {
    try {
      stored = JSON.parse(secretText) || {};
    } catch {
      stored = {};
    }
  }

  const secretKey = String(stored.secret_key || Deno.env.get('STRIPE_SECRET_KEY') || '').trim();
  const webhookSecret = String(stored.webhook_secret || Deno.env.get('STRIPE_WEBHOOK_SECRET') || '').trim();
  const publishableKey = String(row?.public_config?.publishable_key || '').trim();
  const enabled = row ? row.enabled === true : Boolean(secretKey);
  const mode = row?.mode === 'live' ? 'live' : 'test';

  if (requireEnabled && !enabled) {
    throw new Error('Stripe payments are disabled in Super Admin → Payment gateway settings.');
  }
  if (!secretKey) {
    throw new Error('Stripe secret key is not configured. Add it in Super Admin → Payment gateway settings.');
  }

  // Catch accidental test/live mismatches before a customer reaches Checkout.
  const keyLooksLive = /_(live)_/.test(secretKey);
  const keyLooksTest = /_(test)_/.test(secretKey);
  if (mode === 'live' && keyLooksTest) throw new Error('Stripe is set to Live mode but a test API key is configured.');
  if (mode === 'test' && keyLooksLive) throw new Error('Stripe is set to Test mode but a live API key is configured.');

  return { secretKey, webhookSecret, publishableKey, enabled, mode };
}

export function stripeHeaders(secretKey: string, form = false): Record<string, string> {
  return {
    Authorization: `Bearer ${secretKey}`,
    'Stripe-Version': STRIPE_API_VERSION,
    ...(form ? { 'Content-Type': 'application/x-www-form-urlencoded' } : {}),
  };
}

export function stripeConnectHeaders(secretKey: string, json = false): Record<string, string> {
  return {
    Authorization: `Bearer ${secretKey}`,
    'Stripe-Version': STRIPE_CONNECT_API_VERSION,
    ...(json ? { 'Content-Type': 'application/json' } : { 'Content-Type': 'application/x-www-form-urlencoded' }),
  };
}

export function randomIntegrationSuffix(): string {
  const alphabet = 'abcdefghijklmnopqrstuvwxyz';
  const bytes = new Uint8Array(8);
  crypto.getRandomValues(bytes);
  return Array.from(bytes, (byte) => alphabet[byte % alphabet.length]).join('');
}

import { stripeHeaders } from './payment-config.ts';

// Subscription billing only. Invoice payments and connected accounts use their
// own endpoints and are never changed by these helpers.
export async function billingRequest(secret: string, path: string, form?: URLSearchParams, key?: string) {
  const response = await fetch(`https://api.stripe.com/v1/${path}`, {
    method: form ? 'POST' : 'GET',
    headers: { ...stripeHeaders(secret, !!form), ...(key ? { 'Idempotency-Key': key } : {}) },
    ...(form ? { body: form } : {}),
    signal: AbortSignal.timeout(15000),
  });
  const data = await response.json();
  if (!response.ok) throw new Error(data?.error?.message || 'Stripe billing is temporarily unavailable.');
  return data;
}

export async function billingSubscription(secret: string, row: any, businessId: string) {
  if (!row?.stripe_subscription_id || !row?.stripe_customer_id) throw new Error('This business has no Stripe subscription.');
  const sub = await billingRequest(secret, `subscriptions/${encodeURIComponent(row.stripe_subscription_id)}`);
  const customer = typeof sub.customer === 'string' ? sub.customer : sub.customer?.id;
  if (customer !== row.stripe_customer_id || (sub.metadata?.business_id && sub.metadata.business_id !== businessId)) {
    throw new Error('The Stripe subscription does not match this business.');
  }
  return sub;
}

export async function activeBillingSubscriptions(secret: string, customer: string, businessId: string, currentId?: string) {
  const results: any[] = [];
  let cursor = '';
  for (let page = 0; page < 10; page++) {
    const list = await billingRequest(secret, `subscriptions?customer=${encodeURIComponent(customer)}&status=all&limit=100${cursor ? `&starting_after=${encodeURIComponent(cursor)}` : ''}`);
    for (const sub of list.data || []) {
      if (['active', 'trialing', 'past_due', 'unpaid'].includes(sub.status) &&
          (sub.id === currentId || sub.metadata?.business_id === businessId)) results.push(sub);
    }
    if (!list.has_more) return results;
    cursor = list.data?.[list.data.length - 1]?.id;
    if (!cursor) break;
  }
  throw new Error('Too many Stripe subscriptions to check safely. Contact the platform administrator.');
}

export async function pendingPlanChange(secret: string, sub: any, businessId: string) {
  const id = typeof sub.schedule === 'string' ? sub.schedule : sub.schedule?.id;
  if (!id) return null;
  const schedule = await billingRequest(secret, `subscription_schedules/${encodeURIComponent(id)}`);
  if (schedule.status !== 'active' || schedule.subscription !== sub.id) return null;
  if (schedule.metadata?.frindly_cancel === businessId && schedule.end_behavior === 'cancel') return null;
  if (schedule.metadata?.frindly_plan_change !== businessId) {
    throw new Error('This subscription has a schedule managed outside Frindly. Contact support before changing plans.');
  }
  const future = schedule.phases?.find((phase: any) => phase.start_date >= (sub.items?.data?.[0]?.current_period_end || sub.current_period_end));
  const priceId = future?.items?.[0]?.price;
  return priceId ? { scheduleId: id, priceId: typeof priceId === 'string' ? priceId : priceId.id,
    effectiveAt: future.start_date, interval: future.items?.[0]?.price?.recurring?.interval || null } : null;
}

export function subscriptionCancellationPatch(sub: any) {
  const date = Number.isFinite(sub.cancel_at) && sub.cancel_at > 0 ? new Date(sub.cancel_at * 1000).toISOString() : null;
  return { cancel_at_period_end: sub.cancel_at_period_end === true, cancel_at: date };
}

export async function subscriptionPlanPatch(db: any, sub: any) {
  const price = sub.items?.data?.[0]?.price;
  const priceId = typeof price === 'string' ? price : price?.id;
  if (priceId) {
    const { data: plans, error } = await db.from('plans').select('id,stripe_price_id,stripe_annual_price_id');
    if (error) throw error;
    const plan = (plans || []).find((p: any) => p.stripe_price_id === priceId || p.stripe_annual_price_id === priceId);
    if (plan) return { plan_id: plan.id, billing_interval: plan.stripe_annual_price_id === priceId ? 'annual' : 'monthly' };
  }
  // Preserve older subscriptions whose Stripe price was not entered in Plans.
  return sub.metadata?.plan_id ? {
    plan_id: sub.metadata.plan_id,
    billing_interval: sub.metadata.billing_interval === 'annual' ? 'annual' : 'monthly',
  } : {};
}

export async function syncBillingSubscription(db: any, businessId: string, sub: any, currentRow?: any) {
  const item = sub.items?.data?.[0];
  const start = sub.current_period_start ?? item?.current_period_start;
  const end = sub.current_period_end ?? item?.current_period_end;
  if (!Number.isFinite(start) || !Number.isFinite(end) || end < start) throw new Error('Stripe subscription billing period is missing or invalid.');
  const patch = {
    ...await subscriptionPlanPatch(db, sub), ...subscriptionCancellationPatch(sub),
    status: sub.status === 'active' ? 'active' : sub.status === 'trialing' ? 'trialing' : sub.status === 'past_due' ? 'past_due' : 'canceled',
    current_period_start: new Date(start * 1000).toISOString(), current_period_end: new Date(end * 1000).toISOString(),
    trial_ends_at: sub.trial_end ? new Date(sub.trial_end * 1000).toISOString() : null,
    updated_at: new Date().toISOString(),
  };
  if (currentRow?.status === 'suspended') patch.status = 'suspended';
  const { error } = await db.from('subscriptions').update(patch).eq('business_id', businessId).eq('stripe_subscription_id', sub.id);
  if (error) throw error;
  return patch;
}

// Configurations are private to this feature. Never modify a platform's default
// portal or enable a hosted login that could bypass Frindly's role checks.
export async function billingPortalConfiguration(secret: string, purpose: 'owner' | 'cancel' | 'history' | 'update', price?: any) {
  const marker = `frindly-v6187-${purpose}${price ? `-${price.id}` : ''}`;
  let cursor = '';
  for (let page = 0; page < 10; page++) {
    const list = await billingRequest(secret, `billing_portal/configurations?limit=100${cursor ? `&starting_after=${encodeURIComponent(cursor)}` : ''}`);
    const existing = list.data?.find((c: any) => c.active && c.metadata?.frindly_configuration === marker);
    if (existing) {
      const f = existing.features || {}, cancel = f.subscription_cancel;
      if (f.customer_update?.enabled || f.subscription_pause?.enabled ||
          f.payment_method_update?.enabled !== (purpose === 'owner') ||
          f.invoice_history?.enabled !== ['owner', 'history'].includes(purpose) ||
          f.subscription_update?.enabled !== (purpose === 'update') ||
          cancel?.enabled !== ['owner', 'cancel'].includes(purpose) ||
          (cancel.enabled && cancel.mode !== 'at_period_end') ||
          existing.login_page?.enabled) throw new Error('The Stripe billing portal configuration needs review by the platform administrator.');
      return existing.id;
    }
    if (!list.has_more) break;
    cursor = list.data[list.data.length - 1].id;
  }
  const form = new URLSearchParams({
    name: `Frindly ${purpose} billing`, 'metadata[frindly_configuration]': marker,
    'login_page[enabled]': 'false', 'features[customer_update][enabled]': 'false',
    'features[invoice_history][enabled]': String(['owner', 'history'].includes(purpose)),
    'features[payment_method_update][enabled]': String(purpose === 'owner'),
    'features[subscription_cancel][enabled]': String(['owner', 'cancel'].includes(purpose)),
    'features[subscription_cancel][mode]': 'at_period_end',
    'features[subscription_cancel][proration_behavior]': 'none',
    'features[subscription_update][enabled]': String(purpose === 'update'),
  });
  if (purpose === 'update') {
    if (!price?.id || !price?.product) throw new Error('The selected Stripe plan is unavailable.');
    form.set('features[subscription_update][default_allowed_updates][0]', 'price');
    form.set('features[subscription_update][products][0][product]', typeof price.product === 'string' ? price.product : price.product.id);
    form.set('features[subscription_update][products][0][prices][0]', price.id);
    form.set('features[subscription_update][proration_behavior]', 'create_prorations');
  }
  const created = await billingRequest(secret, 'billing_portal/configurations', form, marker);
  return created.id;
}

export function billingReturnUrl(raw: any, request: Request) {
  let target: URL;
  try { target = new URL(String(raw || '')); } catch { throw new Error('Invalid return URL'); }
  if (!['http:', 'https:'].includes(target.protocol)) throw new Error('Return URL must use HTTP or HTTPS');
  const origin = request.headers.get('origin');
  if (origin && origin !== 'null' && new URL(origin).origin !== target.origin) throw new Error('Return URL origin does not match the app origin');
  if ((!origin || origin === 'null') && target.origin !== 'https://frindly.co.nz') throw new Error('Return URL must use the deployed Frindly site');
  target.search = ''; target.hash = 'settings/subscription';
  return target.toString();
}

/**
 * Frindly email transport identity.
 *
 * SECURITY / DELIVERABILITY INVARIANT:
 * The physical From address must come only from trusted server-side
 * configuration. Never pass tenant, business, customer, snapshot or other
 * user-controlled email addresses into the From address. Tenant addresses may
 * be used as Reply-To by the calling function.
 */
const FALLBACK_PLATFORM_FROM = 'notifications@frindly.co.nz';
const EMAIL_RE = /^[^\s@<>]+@[^\s@<>]+\.[^\s@<>]+$/;
const TRUSTED_SENDER_DOMAIN = 'frindly.co.nz';

function isTrustedPlatformSender(email: string): boolean {
  if (!EMAIL_RE.test(email)) return false;
  const domain = email.split('@').pop()?.toLowerCase() || '';
  return domain === TRUSTED_SENDER_DOMAIN || domain.endsWith(`.${TRUSTED_SENDER_DOMAIN}`);
}

export function platformFromEmail(): string {
  const configured = String(
    Deno.env.get('RESEND_FROM_EMAIL') ||
    Deno.env.get('EMAIL_FROM_ADDRESS') ||
    ''
  ).trim();
  // Legacy/non-Frindly values (for example a tenant's own domain) are never
  // accepted as transport senders, even if they remain in environment config.
  return isTrustedPlatformSender(configured) ? configured : FALLBACK_PLATFORM_FROM;
}

export function safeSenderName(value: unknown, fallback = 'Frindly'): string {
  const clean = String(value ?? '').replace(/[<>\r\n]/g, '').trim();
  return clean || fallback;
}

export function platformFrom(displayName: unknown, fallbackName = 'Frindly'): string {
  return `${safeSenderName(displayName, fallbackName)} <${platformFromEmail()}>`;
}

export function validReplyTo(value: unknown): string | undefined {
  const email = String(value ?? '').trim();
  return EMAIL_RE.test(email) ? email : undefined;
}

// STAGED REVIEW ONLY: independent scheduled retry worker for Phase79 receipt outbox.
// Does not mutate Stripe payment state, invoices, or subscription billing.
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';

const json = (body: unknown, status = 200) => new Response(JSON.stringify(body), {
  status, headers: { 'Content-Type': 'application/json' },
});
const escapeHtml = (value: unknown) => String(value ?? '').replace(/[&<>"']/g, (c) =>
  ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#039;' }[c] || c));

Deno.serve(async (req) => {
  if (req.method !== 'POST') return json({ error: 'Method not allowed' }, 405);
  const secret = Deno.env.get('RECEIPT_RETRY_CRON_SECRET');
  if (!secret || req.headers.get('Authorization') !== `Bearer ${secret}`) {
    return json({ error: 'Unauthorized' }, 401);
  }
  const url = Deno.env.get('SUPABASE_URL');
  const service = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY');
  const resendKey = Deno.env.get('RESEND_API_KEY');
  if (!url || !service || !resendKey) return json({ error: 'Missing server configuration' }, 500);
  const db = createClient(url, service, { auth: { persistSession: false } });
  // Quarantine expired in-flight claims before selecting pending receipts. A prior
  // attempt may have been accepted by Resend before its DB completion failed.
  const { data: quarantined, error: quarantineError } = await db.rpc(
    'v6181_quarantine_expired_receipt_claims', { p_limit: 50 },
  );
  if (quarantineError) return json({ error: 'Unable to quarantine expired claims' }, 503);
  const { data: due, error: dueError } = await db.rpc('v6180_due_invoice_payment_receipts', { p_limit: 20 });
  if (dueError) return json({ error: 'Unable to list due receipts' }, 500);
  const results: Array<{ transaction_id: string; outcome: string }> = [];
  for (const item of due || []) {
    const id = String(item.transaction_id);
    const { data: claim, error: claimError } = await db.rpc('v6179_claim_invoice_payment_receipt', { p_transaction_id: id });
    if (claimError || !claim?.claimed) { results.push({ transaction_id: id, outcome: 'not_claimed' }); continue; }
    const token = claim.claim_token;
    try {
      const { data: tx, error: txError } = await db.from('invoice_payment_transactions')
        .select('id,amount,gross_amount,customer_fee_amount,currency,status,stripe_payment_intent_id,stripe_checkout_session_id,invoices(invoice_number,customer_name,customer_email,balance_due),businesses(name,settings)')
        .eq('id', id).single();
      if (txError || !tx || tx.status !== 'succeeded') throw new Error('Settled transaction not available');
      const invoice = tx.invoices as any;
      const business = tx.businesses as any;
      if (!invoice?.customer_email) {
        // No recipient is not a transient provider failure. Release for manual review.
        throw new Error('Missing customer receipt email; manual review required');
      }
      const settings = business?.settings || {};
      const name = String(settings.trading || settings.company || business?.name || 'Your Business');
      const currency = String(tx.currency || 'NZD').toUpperCase();
      const money = (n: unknown) => new Intl.NumberFormat('en-NZ', { style: 'currency', currency }).format(Number(n || 0));
      const number = String(invoice.invoice_number || 'Invoice');
      const html = `<div style="font-family:Arial,sans-serif;line-height:1.6;color:#24313a"><h2>Payment received</h2><p>Hi ${escapeHtml(invoice.customer_name || 'Customer')},</p><p>${escapeHtml(name)} has received your payment for invoice <strong>${escapeHtml(number)}</strong>.</p><table cellpadding="6" cellspacing="0"><tr><td>Invoice payment</td><td>${money(tx.amount)}</td></tr>${Number(tx.customer_fee_amount || 0) > 0 ? `<tr><td>Payment processing fee</td><td>${money(tx.customer_fee_amount)}</td></tr>` : ''}<tr><td>Total charged</td><td>${money(tx.gross_amount)}</td></tr><tr><td>Remaining invoice balance</td><td>${money(invoice.balance_due)}</td></tr></table><p>Reference: ${escapeHtml(tx.stripe_payment_intent_id || tx.stripe_checkout_session_id || 'Stripe payment')}</p><p>Thank you,<br>${escapeHtml(name)}</p></div>`;
      const fromEmail = String(Deno.env.get('RESEND_FROM_EMAIL') || Deno.env.get('EMAIL_FROM_ADDRESS') || 'notifications@frindly.co.nz').trim();
      const response = await fetch('https://api.resend.com/emails', {
        method: 'POST',
        headers: { Authorization: `Bearer ${resendKey}`, 'Content-Type': 'application/json', 'Idempotency-Key': String(claim.idempotency_key) },
        body: JSON.stringify({ from: `${name.replace(/[<>]/g, '')} <${fromEmail}>`, to: [invoice.customer_email], reply_to: settings.email || settings.outboundEmail || undefined, subject: `Payment received for ${number} · ${name}`, html }),
      });
      if (!response.ok) throw new Error(`Email provider HTTP ${response.status}`);
      const sent = await response.json();
      const { data: completed, error: completeError } = await db.rpc('v6179_complete_invoice_payment_receipt', {
        p_transaction_id: id, p_claim_token: token, p_resend_message_id: String(sent?.id || ''),
      });
      if (completeError || completed !== true) throw new Error('Receipt accepted but completion unconfirmed; manual review required');
      results.push({ transaction_id: id, outcome: 'sent' });
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Unknown failure';
      // Fail closed: network timeout, HTTP failure or completion failure may follow provider acceptance.
      // Do not release the claim; expired leases are quarantined by the corrected Phase82 claim RPC.
      // An operator must reconcile with Resend before an explicit retry can be authorised.
      console.warn('Receipt delivery outcome requires reconciliation', id, message);
      results.push({ transaction_id: id, outcome: 'manual_review' });
    }
  }
  return json({ quarantined: quarantined ?? 0, examined: results.length, results });
});

import {createClient} from "https://esm.sh/@supabase/supabase-js@2";
import * as XLSX from "npm:xlsx@0.18.5";

type RawRow={id?:string;source_row_number:number;source_data:Record<string,unknown>};
type ColumnProfile={header:string;key:string;non_empty:number;numeric_ratio:number;date_ratio:number;negative_ratio:number;zero_ratio:number;unique_ratio:number};
type MappingCandidate={source:string;target:string;confidence:number;source_kind:string};
type LogicalRecord={
  record_type:string;source_external_id:string|null;group_key:string;canonical_hash:string;
  display_label:string;normalized_data:Record<string,unknown>;validation_status:"ready"|"warning"|"rejected";
  validation_messages:string[];duplicate_status:"new"|"exact";duplicate_action:string;commit_mode:string;
  member_ids:string[];
};

const cors={"Access-Control-Allow-Origin":"*","Access-Control-Allow-Headers":"authorization, x-client-info, apikey, content-type","Access-Control-Allow-Methods":"POST, OPTIONS"};
const json=(body:unknown,status=200)=>new Response(JSON.stringify(body),{status,headers:{...cors,"Content-Type":"application/json"}});
const clean=(v:unknown)=>String(v??"").replace(/^\uFEFF/,"").trim();
const key=(v:unknown)=>clean(v).toLowerCase().replace(/[^a-z0-9]+/g,"_").replace(/^_|_$/g,"");
const value=(row:Record<string,unknown>,...names:string[])=>{const entries=Object.entries(row);for(const n of names){const wanted=key(n),found=entries.find(([k])=>key(k)===wanted);if(found&&clean(found[1])!=="")return clean(found[1])}return""};
